/**
 * Envío de QR por email — se pega en script.google.com (NO se sube a GitHub).
 *
 * 1. Cambiá CLAVE por una frase larga inventada por vos.
 * 2. Implementar > Nueva implementación > tipo "Aplicación web"
 *      Ejecutar como: Yo   |   Quién tiene acceso: Cualquier usuario
 * 3. Autorizá los permisos (Gmail) y copiá la URL que termina en /exec.
 * 4. Pegá esa URL y la CLAVE en el generador, sección "Envío por email".
 *
 * Si cambiás algo del código, hacé una nueva implementación (o "Administrar
 * implementaciones" > editar > nueva versión) para que se aplique.
 */
var CLAVE = "300126";
var REMITENTE = "REVERENCE"; // nombre que ve quien recibe el correo

function doPost(e) {
  try {
    var d = JSON.parse(e.postData.contents);
    if (d.clave !== CLAVE) return salida_({ ok: false, error: "Clave incorrecta" });
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email || "")) return salida_({ ok: false, error: "Email inválido: " + d.email });
    if (!d.png || !d.dni) return salida_({ ok: false, error: "Faltan datos del QR" });
    if (MailApp.getRemainingDailyQuota() < 1) return salida_({ ok: false, error: "Se agotó el límite diario de Google", restante: 0 });

    var png = Utilities.newBlob(Utilities.base64Decode(d.png), "image/png", "QR_" + d.dni + ".png");
    var mensaje = d.mensaje ? "<p>" + esc_(d.mensaje).replace(/\n/g, "<br>") + "</p>" : "";
    var html = "<div style='font-family:Arial,sans-serif;max-width:480px'>" +
      "<p>Hola " + esc_(d.nombre) + ",</p>" + mensaje +
      "<p>Este es tu código QR de ingreso. Mostralo en la puerta desde el celular o impreso.</p>" +
      "<p><img src='cid:qr' alt='QR de ingreso' width='260' style='display:block'></p>" +
      "<p style='color:#666;font-size:13px'>Guardá la imagen adjunta en tu celular: se puede mostrar sin internet.</p></div>";

    MailApp.sendEmail({
      to: d.email,
      subject: d.asunto || "Tu entrada",
      body: "Hola " + d.nombre + ", te adjuntamos tu código QR de ingreso. Mostralo en la puerta.",
      htmlBody: html,
      name: REMITENTE,
      attachments: [png],
      inlineImages: { qr: png }
    });
    return salida_({ ok: true, restante: MailApp.getRemainingDailyQuota() });
  } catch (err) {
    return salida_({ ok: false, error: String(err) });
  }
}

// Abrir la URL /exec en el navegador sirve para comprobar que está activo.
function doGet() {
  return salida_({ ok: true, mensaje: "El script de envío está activo", restante: MailApp.getRemainingDailyQuota() });
}

function salida_(o) {
  return ContentService.createTextOutput(JSON.stringify(o)).setMimeType(ContentService.MimeType.JSON);
}

function esc_(s) {
  return String(s || "").replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}
